                                                                        if (v >= 18)
                                                                        {
                                                                            if (v == 18)
                                                                            {
                                                                                rw.Boolean(ref this.u15);
                                                                            }

                                                                            rw.Int32(ref this.bulletGuidedMinLifeTime);

                                                                            if (v >= 20)
                                                                            {
                                                                                rw.Single(ref this.bulletGunSpeedCoef);

                                                                                if (v >= 21)
                                                                                {
                                                                                    rw.Int32(ref this.bulletType);

                                                                                    if (v >= 22)
                                                                                    {
                                                                                        rw.Int32(ref this.bulletHomingDamageMinAngle_Deg);
                                                                                        rw.Int32(ref this.bulletHomingDamageMaxAngle_Deg);

                                                                                        if (v >= 23)
                                                                                        {
                                                                                            rw.Single(ref this.bulletRecoil);

                                                                                            if (v >= 24)
                                                                                            {
                                                                                                rw.Single(ref this.bulletGunSpeedCoefRatioMin);
                                                                                                rw.Single(ref this.bulletGunSpeedCoefRatioMax);

                                                                                                if (v >= 25)
                                                                                                {
                                                                                                    rw.Int32(ref this.u16);

                                                                                                    if (v >= 26)
                                                                                                    {
                                                                                                        rw.Boolean(ref this.u17);
                                                                                                    }
                                                                                                }
                                                                                            }
                                                                                        }
                                                                                    }
                                                                                }
                                                                            }
                                                                        }
                                                                    }
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    public virtual void Read(GbxReader r, int v = 0)
    {
        using var rw = new GbxReaderWriter(r);
        ReadWrite(rw, v);
    }

    public virtual void Write(GbxWriter w, int v = 0)
    {
        using var rw = new GbxReaderWriter(w);
        ReadWrite(rw, v);
    }
}
